  const rows=merchants.map(o=>{const subtotal=o.price*i.quantity,shipping=subtotal>=o.freeAt?0:o.shipping,total=round((subtotal+shipping)*(1+i.tax/100)),expected=round(total+i.returnProbability/100*o.returnFee);return {...o,shipping,total,expected,reasons:[...(o.days>i.deadline?['Late arrival']:[]),...(i.returns&&!o.freeReturn?['Paid returns']:[])]}});
